Note existing healthz 405 uses http.Error with JSON body; metrics uses writeAPIError. For new endpoints use writeAPIError (spec: 错误体沿用现有 JSON 外形 — `{"error":{"code":...}}`).

Store methods:

```go
func (s *metricStore) putRule(rule alertRule) (created bool) {
    s.mu.Lock(); defer s.mu.Unlock()
    _, existed := s.rules[rule.ID]
    s.rules[rule.ID] = rule
    return !existed
}

func (s *metricStore) getRule(id string) (alertRule, bool)
func (s *metricStore) deleteRule(id string) bool
func (s *metricStore) listRules() []alertRule  // sorted by id
func (s *metricStore) evalAlerts() []alertOutput // under RLock, uses series
```

evalAlerts needs sumSelector helper that assumes lock held:

```go
func (s *metricStore) sumLocked(metric string, labels map[string]string) (float64, bool) {
    var sum float64
    found := false
    for _, cur := range s.series {
        if cur.name != metric || (cur.typ != "counter" && cur.typ != "gauge") { continue }
        matched := true
        for k, v := range labels {
            got, ok := cur.labels[k]
            if !ok || got != v { matched = false; break }
        }
        if !matched { continue }
        sum += cur.value
        found = true
    }
    return sum, found
}
```

Eval:

```go
func (s *metricStore) evalAlerts() []alertOutput {
    s.mu.RLock(); defer s.mu.RUnlock()
    ids := sorted rule ids
    out := make([]alertOutput, 0, len(ids))
    for _, id := range ids {
        rule := s.rules[id]
        a := alertOutput{ID: id}
        var value float64
        ok := true
        switch rule.Kind {
        case "threshold":
            sum, found := s.sumLocked(rule.Metric, rule.Labels)
            if !found { ok = false } else { value = sum }
        case "ratio":
            num, okN := s.sumLocked(rule.Numerator.Metric, rule.Numerator.Labels)
            den, okD := s.sumLocked(rule.Denominator.Metric, rule.Denominator.Labels)
            if !okN || !okD || den == 0 { ok = false } else { value = num / den }
        }
        if !ok {
            a.State = "no_data"
        } else {
            v := value
            a.Value = &v
            if compare(rule.Operator, value, rule.Threshold) { a.State = "firing" } else { a.State = "inactive" }
        }
        out = append(out, a)
    }
    return out
}
