    if raw.Kind == nil || raw.Operator == nil || raw.Threshold == nil { false }
    kind, op, th := *raw.Kind, *raw.Operator, *raw.Threshold
    if kind != "threshold" && kind != "ratio" { false }
    switch op { case "gt","gte","lt","lte": default: false }
    if math.IsNaN(th) || math.IsInf(th, 0) { false }
    rule := alertRule{ID: id, Kind: kind, Operator: op, Threshold: th}
