func (r alertRule) MarshalJSON() ([]byte, error) {
    m := map[string]any{
        "id": r.ID,
        "kind": r.Kind,
        "operator": r.Operator,
        "threshold": r.Threshold,
    }
    if r.Kind == "threshold" {
