75	// rawRule mirrors the accepted PUT body. Pointers distinguish missing fields
76	// from zero values; strictDecode rejects unknown fields outright.
77	type rawRule struct {
78		Kind        *string            `json:"kind"`
79		Metric      *string            `json:"metric"`
80		Labels      *map[string]string `json:"labels"`
81		Numerator   *json.RawMessage   `json:"numerator"`
82		Denominator *json.RawMessage   `json:"denominator"`
83		Operator    *string            `json:"operator"`
84		Threshold   *float64           `json:"threshold"`
85	}
