92	// decodeRule fully validates a PUT body together with the path id. It never
93	// returns a partially validated rule.
94	func decodeRule(body []byte, id string) (alertRule, bool) {
95		if !identPattern.MatchString(id) {
96			return alertRule{}, false
97		}
98	
99		var raw rawRule
100		if !strictDecode(body, &raw) {
101			return alertRule{}, false
102		}
103		if raw.Kind == nil || raw.Operator == nil || raw.Threshold == nil {
104			return alertRule{}, false
105		}
106		kind, op, threshold := *raw.Kind, *raw.Operator, *raw.Threshold
107		if kind != "threshold" && kind != "ratio" {
108			return alertRule{}, false
109		}
110		switch op {
111		case "gt", "gte", "lt", "lte":
112		default:
113			return alertRule{}, false
114		}
115		if math.IsNaN(threshold) || math.IsInf(threshold, 0) {
116			return alertRule{}, false // encoding/json already rejects NaN/Inf tokens
117		}
118	
119		rule := alertRule{ID: id, Kind: kind, Operator: op, Threshold: threshold}
120		switch kind {
121		case "threshold":
122			if raw.Metric == nil || raw.Labels == nil || raw.Numerator != nil || raw.Denominator != nil {
123				return alertRule{}, false
124			}
125			sel, ok := validateSelector(*raw.Metric, *raw.Labels)
126			if !ok {
127				return alertRule{}, false
128			}
129			rule.Metric, rule.Labels = sel.Metric, sel.Labels
130		case "ratio":
131			if raw.Metric != nil || raw.Labels != nil || raw.Numerator == nil || raw.Denominator == nil {
132				return alertRule{}, false
133			}
134			num, ok := decodeSelector(*raw.Numerator)
135			if !ok {
136				return alertRule{}, false
137			}
138			den, ok := decodeSelector(*raw.Denominator)
139			if !ok {
140				return alertRule{}, false
141			}
142			rule.Numerator, rule.Denominator = num, den
143		}
144		return rule, true
145	}
